import{_ as a,o as t,c as n,a5 as e}from"./chunks/framework.B5tqjWbr.js";const h=JSON.parse('{"title":"PMI-03: 家电变频专题","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"pfc-motor-integration","chapterTitle":"PFC 与电机系统","chapterOrder":40,"category":"PFC 与电机系统","source":"motor","visibility":"public","title":"PMI-03: 家电变频专题","tags":["motor-control"],"status":"learning","summary":"**副标题：从空调到洗衣机——成本敏感型PFC+FOC集成方案的设计实战**","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/pfc-motor-integration/PMI-03-Appliance-Variable-Frequency.md","filePath":"content/motor/pfc-motor-integration/PMI-03-Appliance-Variable-Frequency.md","lastUpdated":null}'),p={name:"content/motor/pfc-motor-integration/PMI-03-Appliance-Variable-Frequency.md"};function i(l,s,m,r,d,o){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="pmi-03-家电变频专题" tabindex="-1">PMI-03: 家电变频专题 <a class="header-anchor" href="#pmi-03-家电变频专题" aria-label="Permalink to &quot;PMI-03: 家电变频专题&quot;">​</a></h1><p><strong>副标题：从空调到洗衣机——成本敏感型PFC+FOC集成方案的设计实战</strong></p><p><strong>难度：</strong> ★★★☆☆</p><hr><h2 id="_1-📌-核心摘要-★★★☆☆-🔰📚" tabindex="-1">1. 📌 核心摘要 ★★★☆☆ 🔰📚 <a class="header-anchor" href="#_1-📌-核心摘要-★★★☆☆-🔰📚" aria-label="Permalink to &quot;1. 📌 核心摘要 ★★★☆☆ 🔰📚&quot;">​</a></h2><p><strong>一句话讲清楚</strong>：家电变频的核心挑战是在极低成本约束下实现PFC+FOC的单芯片集成——用一颗STM32F103/GD32F303同时跑PFC电流环(50~100kHz)和FOC电流环(10~20kHz)，ADC通道复用、中断优先级竞争、母线电容最小化、无传感器启动、IEC 61000-3-2认证——每一项都是成本与性能的极限博弈。</p><p><strong>认知挂钩</strong>：很多工程师以为&quot;家电变频就是工业变频的缩小版，照抄方案降成本就行&quot;，<strong>但家电有工业变频没有的三大约束：成本压到极致（BOM &lt;$8）、噪声敏感（压缩机不能吵到用户）、认证强制（IEC 61000-3-2不过不能上市）！</strong> 工业变频器可以加AFE、用大电容、独立MCU，家电不行——必须用最少的元器件、最小的电容、最便宜的单芯片，同时满足PF&gt;0.99、THD&lt;5%、噪声&lt;40dB。这是完全不同的设计哲学。</p><p><strong>家电变频 vs 工业变频的核心差异：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>家电变频</th><th>工业变频</th></tr></thead><tbody><tr><td>成本目标</td><td>BOM &lt;$8</td><td>BOM &gt;$50</td></tr><tr><td>PFC方案</td><td>单芯片集成</td><td>独立PFC控制器或AFE</td></tr><tr><td>母线电容</td><td>最小化（成本+体积）</td><td>充裕（性能优先）</td></tr><tr><td>传感器</td><td>无传感器/单电阻</td><td>编码器/霍尔</td></tr><tr><td>噪声要求</td><td>&lt; 40dB(A)</td><td>无严格要求</td></tr><tr><td>认证</td><td>IEC 61000-3-2强制</td><td>部分需要</td></tr><tr><td>开发周期</td><td>3~6个月</td><td>12~24个月</td></tr></tbody></table><hr><h2 id="_2-🤔-问题引入-★★★☆☆-🔰" tabindex="-1">2. 🤔 问题引入 ★★★☆☆ 🔰 <a class="header-anchor" href="#_2-🤔-问题引入-★★★☆☆-🔰" aria-label="Permalink to &quot;2. 🤔 问题引入 ★★★☆☆ 🔰&quot;">​</a></h2><h3 id="工程师的真实困惑" tabindex="-1">工程师的真实困惑 <a class="header-anchor" href="#工程师的真实困惑" aria-label="Permalink to &quot;工程师的真实困惑&quot;">​</a></h3><p><strong>场景1：单芯片ADC不够用</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程师A:&quot;用GD32F303做空调变频板，</span></span>
<span class="line"><span>PFC需要3路ADC（电感电流+输入电压+输出电压），</span></span>
<span class="line"><span>FOC需要3路ADC（2相电流+母线电压），</span></span>
<span class="line"><span>加上NTC温度和用户接口，至少需要10路ADC...</span></span>
<span class="line"><span>但GD32F303只有3个ADC，16个外部通道，</span></span>
<span class="line"><span>怎么分配采样时序？&quot;</span></span>
<span class="line"><span>问题现象:</span></span>
<span class="line"><span>- PFC电流采样和FOC电流采样冲突</span></span>
<span class="line"><span>- ADC采样率不够，电流环带宽受限</span></span>
<span class="line"><span>- 采样噪声大，电机抖动</span></span></code></pre></div><p><strong>场景2：压缩机启动困难</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程师B:&quot;空调压缩机启动转矩大，</span></span>
<span class="line"><span>无传感器FOC在低速时角度估算不准，</span></span>
<span class="line"><span>经常启动失败或反转...</span></span>
<span class="line"><span>加了高频注入又太吵，用户投诉...&quot;</span></span>
<span class="line"><span>问题现象:</span></span>
<span class="line"><span>- 压缩机启动失败率&gt;5%</span></span>
<span class="line"><span>- 启动时有明显振动和噪声</span></span>
<span class="line"><span>- 高频注入噪声可被人耳听到</span></span></code></pre></div><p><strong>场景3：EMC认证过不了</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程师C:&quot;PFC+FOC方案EMC测试，</span></span>
<span class="line"><span>传导EMI在150kHz~500kHz超标5dB...</span></span>
<span class="line"><span>增加EMI滤波器后成本超了，</span></span>
<span class="line"><span>减少Y电容后漏电流合格但EMI又超标...&quot;</span></span>
<span class="line"><span>问题现象:</span></span>
<span class="line"><span>- 传导EMI在PFC开关频率附近超标</span></span>
<span class="line"><span>- 辐射EMI在逆变器开关频率附近超标</span></span>
<span class="line"><span>- Y电容受漏电流3.5mA限制，不能无限增加</span></span></code></pre></div><h3 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h3><ul><li>ADC不够 → PFC和FOC的ADC通道复用与采样时序设计</li><li>启动困难 → 压缩机大启动转矩+无传感器低速观测</li><li>EMC超标 → PFC与逆变器EMI的协同抑制与Y电容约束</li></ul><h3 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h3><p>读完本模块，你将能够：</p><p>✅ <strong>理解家电变频架构</strong> - 空调/冰箱/洗衣机/风扇的典型方案差异 ✅ <strong>掌握压缩机驱动特点</strong> - 变负载、大启动转矩、噪声敏感 ✅ <strong>设计单芯片PFC+FOC方案</strong> - ADC复用、中断优先级、资源分配 ✅ <strong>优化成本</strong> - 无传感器方案、单电阻采样、减少母线电容 ✅ <strong>通过认证</strong> - IEC 61000-3-2、EMC、安全认证要点</p><hr><h2 id="_3-💡-直观理解-★★★☆☆-🔰💡" tabindex="-1">3. 💡 直观理解 ★★★☆☆ 🔰💡 <a class="header-anchor" href="#_3-💡-直观理解-★★★☆☆-🔰💡" aria-label="Permalink to &quot;3. 💡 直观理解 ★★★☆☆ 🔰💡&quot;">​</a></h2><h3 id="类比1-家电变频就像-经济型轿车" tabindex="-1">类比1：家电变频就像&quot;经济型轿车&quot; <a class="header-anchor" href="#类比1-家电变频就像-经济型轿车" aria-label="Permalink to &quot;类比1：家电变频就像&quot;经济型轿车&quot;&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工业变频 = 豪华SUV</span></span>
<span class="line"><span>  - 预算充足，性能优先</span></span>
<span class="line"><span>  - 独立PFC控制器 + 独立电机控制器</span></span>
<span class="line"><span>  - 大电容、编码器、AFE</span></span>
<span class="line"><span>  - 成本不是问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>家电变频 = 经济型轿车</span></span>
<span class="line"><span>  - 预算紧张，成本优先</span></span>
<span class="line"><span>  - 单芯片搞定PFC+电机</span></span>
<span class="line"><span>  - 最小电容、无传感器、制动电阻</span></span>
<span class="line"><span>  - 每一分钱都要省</span></span>
<span class="line"><span></span></span>
<span class="line"><span>设计哲学完全不同：</span></span>
<span class="line"><span>  工业变频：性能不够加硬件</span></span>
<span class="line"><span>  家电变频：性能不够优化算法</span></span></code></pre></div><h3 id="类比2-adc复用就像-一条电话线多人共用" tabindex="-1">类比2：ADC复用就像&quot;一条电话线多人共用&quot; <a class="header-anchor" href="#类比2-adc复用就像-一条电话线多人共用" aria-label="Permalink to &quot;类比2：ADC复用就像&quot;一条电话线多人共用&quot;&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10路ADC需求 vs 3个ADC物理单元</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像10个人要打电话，但只有3条电话线</span></span>
<span class="line"><span></span></span>
<span class="line"><span>解决方案：</span></span>
<span class="line"><span>  1. 分时复用：3条线轮流给10个人用（ADC通道切换）</span></span>
<span class="line"><span>  2. 优先级：紧急电话优先（PFC电流采样优先级最高）</span></span>
<span class="line"><span>  3. 降频：不紧急的少打几次（温度采样1Hz就够了）</span></span>
<span class="line"><span>  4. 共享：母线电压PFC和FOC都要用，采一次共享</span></span></code></pre></div><hr><h2 id="_4-🔬-技术原理-★★★☆☆-📚" tabindex="-1">4. 🔬 技术原理 ★★★☆☆ 📚 <a class="header-anchor" href="#_4-🔬-技术原理-★★★☆☆-📚" aria-label="Permalink to &quot;4. 🔬 技术原理 ★★★☆☆ 📚&quot;">​</a></h2><h3 id="_4-1-家电变频架构" tabindex="-1">4.1 家电变频架构 <a class="header-anchor" href="#_4-1-家电变频架构" aria-label="Permalink to &quot;4.1 家电变频架构&quot;">​</a></h3><h4 id="_4-1-1-空调变频架构" tabindex="-1">4.1.1 空调变频架构 <a class="header-anchor" href="#_4-1-1-空调变频架构" aria-label="Permalink to &quot;4.1.1 空调变频架构&quot;">​</a></h4><p>空调是家电中功率最大、技术难度最高的变频应用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  220VAC ──► EMI滤波 ──► 整流桥 ──► PFC(Boost) ──► 母线电容 ──► 逆变器 ──► 压缩机</span></span>
<span class="line"><span>              │                              │                        │</span></span>
<span class="line"><span>         L_CM+L_DM                       400VDC                   FOC控制</span></span>
<span class="line"><span>         C_X+C_Y                       470~680μF               无传感器</span></span></code></pre></div><p><strong>空调变频关键参数：</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>典型值</th><th>说明</th></tr></thead><tbody><tr><td>功率范围</td><td>1~5 kW</td><td>1HP~3HP</td></tr><tr><td>PFC拓扑</td><td>Boost PFC（单相）</td><td>成本最低</td></tr><tr><td>母线电压</td><td>390~400V</td><td>PFC输出</td></tr><tr><td>母线电容</td><td>470~680μF</td><td>电解电容</td></tr><tr><td>电机类型</td><td>BLDC/PMSM压缩机</td><td>内置永磁体</td></tr><tr><td>控制方式</td><td>无传感器FOC</td><td>压缩机封闭，无法安装编码器</td></tr><tr><td>开关频率</td><td>PFC: 50~65kHz, 电机: 10~16kHz</td><td></td></tr><tr><td>认证要求</td><td>IEC 61000-3-2 Class A/D</td><td>强制</td></tr></tbody></table><h4 id="_4-1-2-冰箱变频架构" tabindex="-1">4.1.2 冰箱变频架构 <a class="header-anchor" href="#_4-1-2-冰箱变频架构" aria-label="Permalink to &quot;4.1.2 冰箱变频架构&quot;">​</a></h4><p>冰箱功率较小，但要求极低噪声：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  220VAC ──► EMI滤波 ──► 整流桥 ──► PFC(Boost) ──► 母线电容 ──► 逆变器 ──► 压缩机</span></span>
<span class="line"><span>              │                              │                        │</span></span>
<span class="line"><span>         简化EMI                        390VDC                   FOC/方波</span></span>
<span class="line"><span>         小体积                       220~330μF               无传感器</span></span></code></pre></div><p><strong>冰箱变频特殊要求：</strong></p><ul><li>功率小（100~500W），PFC可以简化</li><li>噪声要求极严格（&lt; 35dB(A)，夜间运行）</li><li>压缩机启停频繁（每天数十次）</li><li>成本极低（BOM &lt; $5）</li></ul><h4 id="_4-1-3-洗衣机变频架构" tabindex="-1">4.1.3 洗衣机变频架构 <a class="header-anchor" href="#_4-1-3-洗衣机变频架构" aria-label="Permalink to &quot;4.1.3 洗衣机变频架构&quot;">​</a></h4><p>洗衣机有独特的制动需求（脱水结束需要快速减速）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  220VAC ──► EMI滤波 ──► 整流桥 ──► PFC(Boost) ──► 母线电容 ──► 逆变器 ──► BLDC电机</span></span>
<span class="line"><span>              │                              │              │           │</span></span>
<span class="line"><span>         标准EMI                        390VDC        制动斩波器    FOC控制</span></span>
<span class="line"><span>                                       330~470μF      +制动电阻    无/有传感器</span></span></code></pre></div><p><strong>洗衣机变频特殊要求：</strong></p><ul><li>需要正反转（洗涤模式）</li><li>脱水时高速运行（800~1400rpm）</li><li>脱水结束需要快速制动→制动能量管理</li><li>负载变化大（空桶vs满载）</li><li>电机通常外置，可安装霍尔传感器</li></ul><h4 id="_4-1-4-风扇变频架构" tabindex="-1">4.1.4 风扇变频架构 <a class="header-anchor" href="#_4-1-4-风扇变频架构" aria-label="Permalink to &quot;4.1.4 风扇变频架构&quot;">​</a></h4><p>风扇是最简单的家电变频应用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  220VAC ──► 整流桥 ──► 母线电容 ──► 逆变器 ──► BLDC电机</span></span>
<span class="line"><span>              │           │              │           │</span></span>
<span class="line"><span>           无PFC!      310VDC        单电阻采样   方波/SPWM</span></span>
<span class="line"><span>                      47~100μF                   无传感器</span></span></code></pre></div><p><strong>风扇变频特殊要求：</strong></p><ul><li>功率极小（20~100W），通常不需要PFC</li><li>成本极致压缩（BOM &lt; $2）</li><li>单电阻采样或无电流采样</li><li>方波控制或简单SPWM即可</li><li>无需IEC 61000-3-2认证（&lt; 75W豁免）</li></ul><h3 id="_4-2-压缩机驱动特点" tabindex="-1">4.2 压缩机驱动特点 <a class="header-anchor" href="#_4-2-压缩机驱动特点" aria-label="Permalink to &quot;4.2 压缩机驱动特点&quot;">​</a></h3><h4 id="_4-2-1-变负载特性" tabindex="-1">4.2.1 变负载特性 <a class="header-anchor" href="#_4-2-1-变负载特性" aria-label="Permalink to &quot;4.2.1 变负载特性&quot;">​</a></h4><p>压缩机负载随运行工况剧烈变化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  转矩</span></span>
<span class="line"><span>    │        ╱╲  高压比工况</span></span>
<span class="line"><span>    │       ╱  ╲</span></span>
<span class="line"><span>    │      ╱    ╲</span></span>
<span class="line"><span>    │     ╱      ╲  正常工况</span></span>
<span class="line"><span>    │    ╱        ╲</span></span>
<span class="line"><span>    │   ╱          ╲</span></span>
<span class="line"><span>    │  ╱            ╲  低压比工况</span></span>
<span class="line"><span>    │ ╱              ╲</span></span>
<span class="line"><span>    │╱                ╲</span></span>
<span class="line"><span>    └──────────────────── 转速</span></span>
<span class="line"><span>    0   1000  2000  3000  4000  rpm</span></span></code></pre></div><p><strong>负载变化因素：</strong></p><table tabindex="0"><thead><tr><th>因素</th><th>影响</th><th>典型变化范围</th></tr></thead><tbody><tr><td>制冷剂压力</td><td>转矩随压力比增大</td><td>1:3</td></tr><tr><td>环境温度</td><td>高温时负载增大</td><td>1:2</td></tr><tr><td>转速</td><td>转矩近似线性增加</td><td>1:4</td></tr><tr><td>启动</td><td>启动转矩是额定的2~3倍</td><td>2~3x</td></tr></tbody></table><p><strong>对控制的影响：</strong></p><ul><li>PI参数需要在宽负载范围内稳定→需要增益调度或鲁棒设计</li><li>负载突变时速度环不能过冲→压缩机过冲可能导致液击</li><li>低速大转矩启动→无传感器观测器精度下降</li></ul><h4 id="_4-2-2-启动转矩大" tabindex="-1">4.2.2 启动转矩大 <a class="header-anchor" href="#_4-2-2-启动转矩大" aria-label="Permalink to &quot;4.2.2 启动转矩大&quot;">​</a></h4><p>压缩机启动面临三大挑战：</p><p><strong>1. 静摩擦力矩大</strong></p><p>压缩机停机后制冷剂可能液化并流回压缩机，导致启动时需要克服液态制冷剂的阻力：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>T</mi><mrow><mi>s</mi><mi>t</mi><mi>a</mi><mi>r</mi><mi>t</mi></mrow></msub><mo>=</mo><msub><mi>T</mi><mrow><mi>f</mi><mi>r</mi><mi>i</mi><mi>c</mi><mi>t</mi><mi>i</mi><mi>o</mi><mi>n</mi></mrow></msub><mo>+</mo><msub><mi>T</mi><mrow><mi>g</mi><mi>a</mi><mi>s</mi></mrow></msub><mo>+</mo><msub><mi>T</mi><mrow><mi>l</mi><mi>i</mi><mi>q</mi><mi>u</mi><mi>i</mi><mi>d</mi></mrow></msub><mo>≈</mo><mo>(</mo><mn>2</mn><mo>∼</mo><mn>3</mn><mo>)</mo><mo>×</mo><msub><mi>T</mi><mrow><mi>r</mi><mi>a</mi><mi>t</mi><mi>e</mi><mi>d</mi></mrow></msub></mrow><annotation encoding="application/x-tex">T_{start} = T_{friction} + T_{gas} + T_{liquid} \\approx (2 \\sim 3) \\times T_{rated} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.036108em;vertical-align:-0.286108em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mord mathit">t</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">t</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">i</span><span class="mord mathit">c</span><span class="mord mathit">t</span><span class="mord mathit">i</span><span class="mord mathit">o</span><span class="mord mathit">n</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.03588em;">g</span><span class="mord mathit">a</span><span class="mord mathit">s</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span><span class="mord mathit">i</span><span class="mord mathit" style="margin-right:0.03588em;">q</span><span class="mord mathit">u</span><span class="mord mathit">i</span><span class="mord mathit">d</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">≈</span><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mrel">∼</span><span class="mord mathrm">3</span><span class="mclose">)</span><span class="mbin">×</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">a</span><span class="mord mathit">t</span><span class="mord mathit">e</span><span class="mord mathit">d</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span></p><p><strong>2. 无传感器低速启动困难</strong></p><p>无传感器FOC在低速（&lt; 5Hz）时反电动势极小，观测器信噪比极低：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>e</mi><mrow><mi>b</mi><mi>a</mi><mi>c</mi><mi>k</mi></mrow></msub><mo>=</mo><msub><mi>ω</mi><mi>e</mi></msub><mo>⋅</mo><msub><mi>ψ</mi><mi>f</mi></msub><mo>∝</mo><msub><mi>ω</mi><mi>e</mi></msub></mrow><annotation encoding="application/x-tex">e_{back} = \\omega_e \\cdot \\psi_f \\propto \\omega_e </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.980548em;vertical-align:-0.286108em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">e</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">b</span><span class="mord mathit">a</span><span class="mord mathit">c</span><span class="mord mathit" style="margin-right:0.03148em;">k</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">e</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">⋅</span><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ψ</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">∝</span><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">e</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span></p><p>当<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>ω</mi><mi>e</mi></msub><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">\\omega_e \\to 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.79444em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.03588em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord mathit">e</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">→</span><span class="mord mathrm">0</span></span></span></span>时，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>e</mi><mrow><mi>b</mi><mi>a</mi><mi>c</mi><mi>k</mi></mrow></msub><mo>→</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">e_{back} \\to 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.79444em;vertical-align:-0.15em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">e</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">b</span><span class="mord mathit">a</span><span class="mord mathit">c</span><span class="mord mathit" style="margin-right:0.03148em;">k</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">→</span><span class="mord mathrm">0</span></span></span></span>，滑模观测器/磁链观测器无法工作。</p><p><strong>3. 启动策略选择</strong></p><table tabindex="0"><thead><tr><th>启动策略</th><th>原理</th><th>优点</th><th>缺点</th><th>适用场景</th></tr></thead><tbody><tr><td>开环V/f启动</td><td>固定V/f比开环运行</td><td>简单</td><td>可能失步、反转</td><td>低成本方案</td></tr><tr><td>I-f启动</td><td>电流幅值+频率开环</td><td>比V/f更稳定</td><td>切换到闭环有冲击</td><td>主流方案</td></tr><tr><td>高频注入</td><td>注入高频信号检测位置</td><td>真正的零速启动</td><td>噪声大</td><td>不适合家电</td></tr><tr><td>转子定位+I-f</td><td>先定位再I-f启动</td><td>避免反转</td><td>定位时间增加</td><td>推荐方案</td></tr></tbody></table><p><strong>推荐方案：转子定位 + I-f启动 + 平滑切换到FOC</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  阶段1: 转子定位（0.5~1秒）</span></span>
<span class="line"><span>    - 注入d轴直流电流，将转子拉到已知位置</span></span>
<span class="line"><span>    - 电流约50%额定值，避免过大冲击</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  阶段2: I-f开环启动（1~3秒）</span></span>
<span class="line"><span>    - 电流幅值恒定，频率从0缓慢上升</span></span>
<span class="line"><span>    - 频率斜坡率根据负载调整</span></span>
<span class="line"><span>    - 保持电压角超前电流角（保证电动转矩）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  阶段3: 切换到FOC闭环（转速&gt;10%额定）</span></span>
<span class="line"><span>    - 观测器精度足够时切换</span></span>
<span class="line"><span>    - 切换瞬间角度和电流必须连续</span></span>
<span class="line"><span>    - 使用渐变因子平滑过渡</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  阶段4: FOC正常运行</span></span>
<span class="line"><span>    - 速度环+电流环双环控制</span></span>
<span class="line"><span>    - 根据负载调整速度环PI参数</span></span></code></pre></div><h4 id="_4-2-3-噪声敏感" tabindex="-1">4.2.3 噪声敏感 <a class="header-anchor" href="#_4-2-3-噪声敏感" aria-label="Permalink to &quot;4.2.3 噪声敏感&quot;">​</a></h4><p>家电压缩机的噪声限制极为严格：</p><table tabindex="0"><thead><tr><th>噪声源</th><th>频率范围</th><th>产生原因</th><th>抑制方法</th></tr></thead><tbody><tr><td>电磁噪声</td><td>f_sw及其谐波</td><td>电流纹波导致定子振动</td><td>提高开关频率/随机PWM</td></tr><tr><td>机械噪声</td><td>1~5kHz</td><td>转矩脉动导致转子振动</td><td>降低转矩脉动</td></tr><tr><td>气流噪声</td><td>宽带</td><td>制冷剂流动</td><td>压缩机设计优化</td></tr><tr><td>PFC噪声</td><td>f_sw,PFC</td><td>电感振动</td><td>浸漆电感/固定方式</td></tr></tbody></table><p><strong>随机PWM技术：</strong> 通过随机化开关周期或零向量分配，将EMI噪声能量从离散谱线分散到连续谱，降低可听噪声：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>T</mi><mrow><mi>s</mi><mi>w</mi></mrow></msub><mo>(</mo><mi>k</mi><mo>)</mo><mo>=</mo><msub><mi>T</mi><mrow><mi>s</mi><mi>w</mi><mo separator="true">,</mo><mi>a</mi><mi>v</mi><mi>g</mi></mrow></msub><mo>⋅</mo><mo>(</mo><mn>1</mn><mo>+</mo><mi>δ</mi><mo>⋅</mo><mi>r</mi><mo>(</mo><mi>k</mi><mo>)</mo><mo>)</mo></mrow><annotation encoding="application/x-tex">T_{sw}(k) = T_{sw,avg} \\cdot (1 + \\delta \\cdot r(k)) </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1.036108em;vertical-align:-0.286108em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mord mathit" style="margin-right:0.02691em;">w</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">s</span><span class="mord mathit" style="margin-right:0.02691em;">w</span><span class="mpunct">,</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.03588em;">v</span><span class="mord mathit" style="margin-right:0.03588em;">g</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">⋅</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.03785em;">δ</span><span class="mbin">⋅</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="mclose">)</span><span class="mclose">)</span></span></span></span></span></p><p>其中<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>r</mi><mo>(</mo><mi>k</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">r(k)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="mclose">)</span></span></span></span>为[-1, 1]均匀分布随机数，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>δ</mi></mrow><annotation encoding="application/x-tex">\\delta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.03785em;">δ</span></span></span></span>为随机化幅度（0.05~0.15）。</p><h3 id="_4-3-单芯片pfc-foc方案详解" tabindex="-1">4.3 单芯片PFC+FOC方案详解 <a class="header-anchor" href="#_4-3-单芯片pfc-foc方案详解" aria-label="Permalink to &quot;4.3 单芯片PFC+FOC方案详解&quot;">​</a></h3><h4 id="_4-3-1-stm32f103-gd32f303方案" tabindex="-1">4.3.1 STM32F103/GD32F303方案 <a class="header-anchor" href="#_4-3-1-stm32f103-gd32f303方案" aria-label="Permalink to &quot;4.3.1 STM32F103/GD32F303方案&quot;">​</a></h4><p>STM32F103和GD32F303是家电变频最主流的MCU选择：</p><p><strong>资源清单：</strong></p><table tabindex="0"><thead><tr><th>资源</th><th>STM32F103RCT6</th><th>GD32F303RCT6</th><th>PFC+FOC需求</th></tr></thead><tbody><tr><td>内核</td><td>Cortex-M3 72MHz</td><td>Cortex-M4F 108MHz</td><td>-</td></tr><tr><td>ADC</td><td>3×12-bit, 1Msps</td><td>3×12-bit, 2.4Msps</td><td>3个ADC单元</td></tr><tr><td>ADC通道</td><td>16ch(ADC1)+16ch(ADC2)</td><td>16ch×3</td><td>≥10ch</td></tr><tr><td>定时器</td><td>TIM1(高级)+TIM2-4</td><td>TIM0(高级)+TIM1-4</td><td>2个高级定时器</td></tr><tr><td>PWM通道</td><td>4ch(TIM1)+9ch</td><td>4ch(TIM0)+12ch</td><td>PFC:1ch+FOC:6ch</td></tr><tr><td>DMA</td><td>2单元,7ch</td><td>2单元,8ch</td><td>≥2ch</td></tr><tr><td>Flash</td><td>256KB</td><td>256KB</td><td>≥128KB</td></tr><tr><td>RAM</td><td>48KB</td><td>32KB</td><td>≥16KB</td></tr></tbody></table><p><strong>关键问题：STM32F103RCT6有TIM1和TIM8两个高级定时器，但TIM8的DMA请求通道与TIM1不同，需软件协调两个定时器的触发时序。</strong></p><p><strong>解决方案：</strong></p><table tabindex="0"><thead><tr><th>方案</th><th>PFC定时器</th><th>FOC定时器</th><th>可行性</th></tr></thead><tbody><tr><td>方案A</td><td>TIM1(CH1)</td><td>TIM1(CH2-4)</td><td>⚠️ 同一定时器，频率必须相同或整数倍</td></tr><tr><td>方案B</td><td>TIM1(CH1)</td><td>通用定时器+软件</td><td>✅ 灵活但FOC PWM精度降低</td></tr><tr><td>方案C</td><td>换用GD32F303(有TIM0+TIM1)</td><td>-</td><td>✅ 推荐方案</td></tr></tbody></table><p><strong>GD32F303双高级定时器方案（推荐）：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TIM0 (高级定时器): FOC PWM</span></span>
<span class="line"><span>  - CH0/CH1/CH2: 三相PWM (U/V/W)</span></span>
<span class="line"><span>  - CH3: 制动斩波器PWM</span></span>
<span class="line"><span>  - 中心对齐模式, f_sw = 16kHz</span></span>
<span class="line"><span>  - ADC1由TIM0触发</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TIM1 (高级定时器): PFC PWM</span></span>
<span class="line"><span>  - CH0: PFC MOSFET驱动</span></span>
<span class="line"><span>  - 中心对齐模式, f_sw = 65kHz</span></span>
<span class="line"><span>  - ADC2由TIM1触发</span></span></code></pre></div><h4 id="_4-3-2-pfc中断与foc中断优先级" tabindex="-1">4.3.2 PFC中断与FOC中断优先级 <a class="header-anchor" href="#_4-3-2-pfc中断与foc中断优先级" aria-label="Permalink to &quot;4.3.2 PFC中断与FOC中断优先级&quot;">​</a></h4><p><strong>中断优先级设计原则：</strong></p><ol><li>PFC电流环频率最高（65kHz），执行时间最短，优先级最高</li><li>FOC电流环频率次高（16kHz），可被PFC中断抢占</li><li>速度环和PFC电压环频率低，优先级最低</li></ol><p><strong>NVIC优先级配置：</strong></p><table tabindex="0"><thead><tr><th>优先级</th><th>中断源</th><th>执行内容</th><th>频率</th><th>执行时间</th></tr></thead><tbody><tr><td>0（最高）</td><td>TIM1_UP</td><td>PFC电流环</td><td>65kHz</td><td>3~5μs</td></tr><tr><td>1</td><td>TIM0_UP</td><td>FOC电流环</td><td>16kHz</td><td>8~12μs</td></tr><tr><td>2</td><td>TIM0_UP(降频)</td><td>速度环+PFC电压环</td><td>1kHz</td><td>5~10μs</td></tr><tr><td>3</td><td>DMA/UART</td><td>通信</td><td>100Hz</td><td>2~5μs</td></tr></tbody></table><p><strong>中断嵌套时序：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时间轴 (μs):</span></span>
<span class="line"><span>0    5    10   15   20   25   30   35   40   45   50   55   60</span></span>
<span class="line"><span>│    │    │    │    │    │    │    │    │    │    │    │    │</span></span>
<span class="line"><span>│PFC │    │PFC │    │PFC │    │PFC │    │PFC │    │PFC │    │</span></span>
<span class="line"><span>│ 3μs│    │ 3μs│    │ 3μs│    │ 3μs│    │ 3μs│    │ 3μs│    │</span></span>
<span class="line"><span>│    │FOC │    │    │    │FOC │    │    │    │FOC │    │    │</span></span>
<span class="line"><span>│    │12μs│    │    │    │12μs│    │    │    │12μs│    │    │</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PFC中断每15.4μs一次(65kHz)</span></span>
<span class="line"><span>FOC中断每62.5μs一次(16kHz)</span></span>
<span class="line"><span>PFC中断可以抢占FOC中断</span></span></code></pre></div><p><strong>最恶劣情况分析：</strong> FOC中断执行期间被PFC中断抢占，FOC总执行时间 = FOC自身时间 + PFC抢占时间：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>t</mi><mrow><mi>F</mi><mi>O</mi><mi>C</mi><mo separator="true">,</mo><mi>m</mi><mi>a</mi><mi>x</mi></mrow></msub><mo>=</mo><msub><mi>t</mi><mrow><mi>F</mi><mi>O</mi><mi>C</mi></mrow></msub><mo>+</mo><msub><mi>n</mi><mrow><mi>p</mi><mi>r</mi><mi>e</mi><mi>e</mi><mi>m</mi><mi>p</mi><mi>t</mi></mrow></msub><mo>×</mo><msub><mi>t</mi><mrow><mi>P</mi><mi>F</mi><mi>C</mi></mrow></msub></mrow><annotation encoding="application/x-tex">t_{FOC,max} = t_{FOC} + n_{preempt} \\times t_{PFC} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.61508em;"></span><span class="strut bottom" style="height:0.9011879999999999em;vertical-align:-0.286108em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mpunct">,</span><span class="mord mathit">m</span><span class="mord mathit">a</span><span class="mord mathit">x</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">+</span><span class="mord"><span class="mord mathit">n</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">p</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit">e</span><span class="mord mathit">m</span><span class="mord mathit">p</span><span class="mord mathit">t</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">×</span><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span></span></p><p>其中<span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>n</mi><mrow><mi>p</mi><mi>r</mi><mi>e</mi><mi>e</mi><mi>m</mi><mi>p</mi><mi>t</mi></mrow></msub></mrow><annotation encoding="application/x-tex">n_{preempt}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.716668em;vertical-align:-0.286108em;"></span><span class="base textstyle uncramped"><span class="mord"><span class="mord mathit">n</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">p</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit">e</span><span class="mord mathit">m</span><span class="mord mathit">p</span><span class="mord mathit">t</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span>为FOC执行期间被PFC抢占的次数：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>n</mi><mrow><mi>p</mi><mi>r</mi><mi>e</mi><mi>e</mi><mi>m</mi><mi>p</mi><mi>t</mi></mrow></msub><mo>=</mo><mo>⌈</mo><mfrac><mrow><msub><mi>t</mi><mrow><mi>F</mi><mi>O</mi><mi>C</mi></mrow></msub></mrow><mrow><msub><mi>T</mi><mrow><mi>P</mi><mi>F</mi><mi>C</mi></mrow></msub></mrow></mfrac><mo>⌉</mo><mo>=</mo><mo>⌈</mo><mfrac><mrow><mn>1</mn><mn>2</mn></mrow><mrow><mn>1</mn><mn>5</mn><mi mathvariant="normal">.</mi><mn>4</mn></mrow></mfrac><mo>⌉</mo><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n_{preempt} = \\lceil \\frac{t_{FOC}}{T_{PFC}} \\rceil = \\lceil \\frac{12}{15.4} \\rceil = 1 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.32144em;"></span><span class="strut bottom" style="height:2.1574400000000002em;vertical-align:-0.8360000000000001em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit">n</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">p</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit">e</span><span class="mord mathit">m</span><span class="mord mathit">p</span><span class="mord mathit">t</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mopen">⌈</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mclose">⌉</span><span class="mrel">=</span><span class="mopen">⌈</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">.</span><span class="mord mathrm">4</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mclose">⌉</span><span class="mrel">=</span><span class="mord mathrm">1</span></span></span></span></span></p> t_{FOC,max} = 12 + 1 \\times 3 = 15 \\text{ μs} &lt; T_{FOC} = 62.5 \\text{ μs} ✅ <p>CPU占用率：</p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi><mi>P</mi><msub><mi>U</mi><mrow><mi>l</mi><mi>o</mi><mi>a</mi><mi>d</mi></mrow></msub><mo>=</mo><mfrac><mrow><msub><mi>t</mi><mrow><mi>P</mi><mi>F</mi><mi>C</mi></mrow></msub></mrow><mrow><msub><mi>T</mi><mrow><mi>P</mi><mi>F</mi><mi>C</mi></mrow></msub></mrow></mfrac><mo>+</mo><mfrac><mrow><msub><mi>t</mi><mrow><mi>F</mi><mi>O</mi><mi>C</mi></mrow></msub></mrow><mrow><msub><mi>T</mi><mrow><mi>F</mi><mi>O</mi><mi>C</mi></mrow></msub></mrow></mfrac><mo>=</mo><mfrac><mrow><mn>3</mn></mrow><mrow><mn>1</mn><mn>5</mn><mi mathvariant="normal">.</mi><mn>4</mn></mrow></mfrac><mo>+</mo><mfrac><mrow><mn>1</mn><mn>2</mn></mrow><mrow><mn>6</mn><mn>2</mn><mi mathvariant="normal">.</mi><mn>5</mn></mrow></mfrac><mo>=</mo><mn>1</mn><mn>9</mn><mi mathvariant="normal">.</mi><mn>5</mn><mi mathvariant="normal">%</mi><mo>+</mo><mn>1</mn><mn>9</mn><mi mathvariant="normal">.</mi><mn>2</mn><mi mathvariant="normal">%</mi><mo>=</mo><mn>3</mn><mn>8</mn><mi mathvariant="normal">.</mi><mn>7</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">CPU_{load} = \\frac{t_{PFC}}{T_{PFC}} + \\frac{t_{FOC}}{T_{FOC}} = \\frac{3}{15.4} + \\frac{12}{62.5} = 19.5\\% + 19.2\\% = 38.7\\% </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.32144em;"></span><span class="strut bottom" style="height:2.1574400000000002em;vertical-align:-0.8360000000000001em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord"><span class="mord mathit" style="margin-right:0.10903em;">U</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.10903em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.01968em;">l</span><span class="mord mathit">o</span><span class="mord mathit">a</span><span class="mord mathit">d</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">+</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">T</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit">t</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:0em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.13889em;">F</span><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mord mathrm">.</span><span class="mord mathrm">4</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">3</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mbin">+</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">6</span><span class="mord mathrm">2</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">.</span><span class="mord mathrm">5</span><span class="mord mathrm">%</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">9</span><span class="mord mathrm">.</span><span class="mord mathrm">2</span><span class="mord mathrm">%</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">8</span><span class="mord mathrm">.</span><span class="mord mathrm">7</span><span class="mord mathrm">%</span></span></span></span></span></p><p>剩余61.3%的CPU时间可用于速度环、PFC电压环、通信等任务，余量充足。</p><h4 id="_4-3-3-adc资源分配" tabindex="-1">4.3.3 ADC资源分配 <a class="header-anchor" href="#_4-3-3-adc资源分配" aria-label="Permalink to &quot;4.3.3 ADC资源分配&quot;">​</a></h4><p><strong>ADC通道分配方案（GD32F303）：</strong></p><table tabindex="0"><thead><tr><th>ADC单元</th><th>通道</th><th>采样信号</th><th>采样率</th><th>触发源</th></tr></thead><tbody><tr><td>ADC0</td><td>CH0</td><td>FOC相电流A (Ia)</td><td>16kHz</td><td>TIM0 TRGO</td></tr><tr><td>ADC0</td><td>CH1</td><td>FOC相电流B (Ib)</td><td>16kHz</td><td>TIM0 TRGO</td></tr><tr><td>ADC0</td><td>CH2</td><td>母线电压 (Vdc)</td><td>16kHz</td><td>TIM0 TRGO</td></tr><tr><td>ADC1</td><td>CH0</td><td>PFC电感电流 (IL)</td><td>65kHz</td><td>TIM1 TRGO</td></tr><tr><td>ADC1</td><td>CH1</td><td>PFC输入电压 (Vin)</td><td>65kHz</td><td>TIM1 TRGO</td></tr><tr><td>ADC1</td><td>CH2</td><td>PFC输出电压 (Vdc)</td><td>65kHz</td><td>TIM1 TRGO</td></tr><tr><td>ADC2</td><td>CH0</td><td>散热器NTC温度</td><td>10Hz</td><td>软件触发</td></tr><tr><td>ADC2</td><td>CH1</td><td>环境NTC温度</td><td>10Hz</td><td>软件触发</td></tr><tr><td>ADC2</td><td>CH2</td><td>用户电位器</td><td>100Hz</td><td>软件触发</td></tr></tbody></table><p><strong>关键设计：母线电压(Vdc)由ADC0和ADC1各采一路，PFC和FOC各自使用，避免跨ADC共享数据的延迟。</strong></p><p><strong>ADC采样时序：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TIM0 (FOC, 16kHz, T=62.5μs):</span></span>
<span class="line"><span>  ┌──────────────────────┐</span></span>
<span class="line"><span>  │         PWM          │</span></span>
<span class="line"><span>  ┘                      └──────</span></span>
<span class="line"><span>       ↑ ADC0触发</span></span>
<span class="line"><span>       Ia, Ib, Vdc 采样（3个通道顺序采样，约3μs）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>TIM1 (PFC, 65kHz, T=15.4μs):</span></span>
<span class="line"><span>  ┌──────┐</span></span>
<span class="line"><span>  │ PWM  │</span></span>
<span class="line"><span>  ┘      └──────────────</span></span>
<span class="line"><span>     ↑ ADC1触发</span></span>
<span class="line"><span>     IL, Vin, Vdc 采样（3个通道顺序采样，约1.5μs）</span></span></code></pre></div><p><strong>ADC采样冲突避免：</strong></p><p>ADC0和ADC1是独立的ADC单元，可以并行采样，互不干扰。但需要注意：</p><ul><li>两个ADC不能同时访问同一个通道（硬件限制）</li><li>Vdc信号需要两路独立的采样电路（分压电阻+滤波电容）</li><li>或者使用ADC注入组（inject group）实现紧急采样</li></ul><h3 id="_4-4-成本优化" tabindex="-1">4.4 成本优化 <a class="header-anchor" href="#_4-4-成本优化" aria-label="Permalink to &quot;4.4 成本优化&quot;">​</a></h3><h4 id="_4-4-1-无传感器方案" tabindex="-1">4.4.1 无传感器方案 <a class="header-anchor" href="#_4-4-1-无传感器方案" aria-label="Permalink to &quot;4.4.1 无传感器方案&quot;">​</a></h4><p>无传感器FOC省去了编码器/霍尔传感器，是家电变频的标配：</p><table tabindex="0"><thead><tr><th>方案</th><th>省去器件</th><th>节省成本</th><th>适用转速范围</th></tr></thead><tbody><tr><td>滑模观测器(SMO)</td><td>编码器</td><td>$2~5</td><td>&gt; 10% 额定转速</td></tr><tr><td>磁链观测器</td><td>编码器</td><td>$2~5</td><td>&gt; 5% 额定转速</td></tr><tr><td>高频注入</td><td>编码器</td><td>$2~5</td><td>0~10% 额定转速</td></tr><tr><td>反电动势过零</td><td>霍尔+编码器</td><td>$3~8</td><td>&gt; 5% 额定转速（方波控制）</td></tr></tbody></table><p><strong>家电主流方案：</strong> I-f启动 + 滑模观测器/磁链观测器FOC，成本节省$2~5/台。</p><h4 id="_4-4-2-单电阻采样-pfc的adc复用" tabindex="-1">4.4.2 单电阻采样+PFC的ADC复用 <a class="header-anchor" href="#_4-4-2-单电阻采样-pfc的adc复用" aria-label="Permalink to &quot;4.4.2 单电阻采样+PFC的ADC复用&quot;">​</a></h4><p>单电阻采样（Single-Shunt）只使用母线直流母线上的一个电流采样电阻，通过PWM重构三相电流：</p><p><strong>传统三电阻方案 vs 单电阻方案：</strong></p><table tabindex="0"><thead><tr><th>对比维度</th><th>三电阻采样</th><th>单电阻采样</th></tr></thead><tbody><tr><td>电流传感器</td><td>3个运放+3个ADC通道</td><td>1个运放+1个ADC通道</td></tr><tr><td>BOM成本</td><td>$0.6~1.0</td><td>$0.2~0.3</td></tr><tr><td>采样精度</td><td>高（直接测量）</td><td>中（需要重构）</td></tr><tr><td>最小脉宽限制</td><td>无</td><td>有（&lt; 2μs的PWM脉宽无法采样）</td></tr><tr><td>算法复杂度</td><td>低</td><td>高（PWM移相+电流重构）</td></tr><tr><td>适用场景</td><td>高性能伺服</td><td>家电变频</td></tr></tbody></table><p><strong>单电阻采样与PFC的ADC复用挑战：</strong></p><p>单电阻采样需要在每个PWM周期内采样2~3次（重构三相电流），加上PFC的采样需求，ADC时序极为紧张：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一个FOC PWM周期内(62.5μs)的ADC采样时序：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ┌─┐         ┌──────┐         ┌──────┐</span></span>
<span class="line"><span>  │ │         │      │         │      │</span></span>
<span class="line"><span>  ┘ └─────────┘      └─────────┘      └──</span></span>
<span class="line"><span>  ↑  ↑              ↑              ↑</span></span>
<span class="line"><span>  │  采样1           采样2          采样3</span></span>
<span class="line"><span>  │  (Ibus, Ia重构)  (Ibus, Ib重构) (PFC: IL, Vin)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  PFC采样(65kHz周期内)</span></span></code></pre></div><p><strong>解决方案：</strong></p><ol><li>PFC采样在FOC PWM的零向量期间插入，避免与FOC电流采样冲突</li><li>降低PFC采样率到32.5kHz（FOC每2个周期采样1次PFC），释放ADC时间</li><li>使用ADC注入组实现PFC紧急采样（过流保护）</li></ol><h4 id="_4-4-3-减少母线电容" tabindex="-1">4.4.3 减少母线电容 <a class="header-anchor" href="#_4-4-3-减少母线电容" aria-label="Permalink to &quot;4.4.3 减少母线电容&quot;">​</a></h4><p>母线电容是BOM成本的大头（电解电容占$0.5~1.5），减少电容容值可以显著降低成本：</p><p><strong>电容容值与成本的关系：</strong></p><table tabindex="0"><thead><tr><th>容值</th><th>规格</th><th>单价</th><th>数量</th><th>总成本</th></tr></thead><tbody><tr><td>680μF</td><td>450V/680μF</td><td>$1.20</td><td>1</td><td>$1.20</td></tr><tr><td>470μF</td><td>450V/470μF</td><td>$0.90</td><td>1</td><td>$0.90</td></tr><tr><td>330μF</td><td>450V/330μF</td><td>$0.70</td><td>1</td><td>$0.70</td></tr><tr><td>220μF</td><td>450V/220μF</td><td>$0.50</td><td>2</td><td>$1.00</td></tr></tbody></table><p><strong>减少电容的代价：</strong></p><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi mathvariant="normal">Δ</mi><msub><mi>V</mi><mrow><mi>d</mi><mi>c</mi></mrow></msub><mo>=</mo><mfrac><mrow><msub><mi>P</mi><mrow><mi>o</mi><mi>u</mi><mi>t</mi></mrow></msub></mrow><mrow><mn>2</mn><mi>ω</mi><mo>⋅</mo><msub><mi>C</mi><mrow><mi>b</mi><mi>u</mi><mi>s</mi></mrow></msub><mo>⋅</mo><msub><mi>V</mi><mrow><mi>d</mi><mi>c</mi></mrow></msub></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\Delta V_{dc} = \\frac{P_{out}}{2\\omega \\cdot C_{bus} \\cdot V_{dc}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.36033em;"></span><span class="strut bottom" style="height:2.19633em;vertical-align:-0.8360000000000001em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord mathrm">Δ</span><span class="mord"><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.22222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">d</span><span class="mord mathit">c</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.686em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord mathrm">2</span><span class="mord mathit" style="margin-right:0.03588em;">ω</span><span class="mbin">⋅</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.07153em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">b</span><span class="mord mathit">u</span><span class="mord mathit">s</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">⋅</span><span class="mord"><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.22222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">d</span><span class="mord mathit">c</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.13889em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">o</span><span class="mord mathit">u</span><span class="mord mathit">t</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></span></p><table tabindex="0"><thead><tr><th>容值</th><th>纹波电压</th><th>纹波比</th><th>评价</th></tr></thead><tbody><tr><td>680μF</td><td>11.7V</td><td>2.9%</td><td>充裕</td></tr><tr><td>470μF</td><td>16.9V</td><td>4.2%</td><td>可接受</td></tr><tr><td>330μF</td><td>24.1V</td><td>6.0%</td><td>偏大，需要母线电压前馈补偿</td></tr><tr><td>220μF</td><td>36.2V</td><td>9.1%</td><td>过大，电机转矩脉动明显</td></tr></tbody></table><p><strong>减少电容的补偿措施：</strong></p><ol><li><strong>母线电压前馈补偿</strong>：在逆变器控制中补偿母线纹波对输出电压的影响</li></ol><p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>V</mi><mrow><mi>r</mi><mi>e</mi><mi>f</mi><mo separator="true">,</mo><mi>c</mi><mi>o</mi><mi>m</mi><mi>p</mi></mrow></msub><mo>=</mo><msub><mi>V</mi><mrow><mi>r</mi><mi>e</mi><mi>f</mi></mrow></msub><mo>×</mo><mfrac><mrow><msub><mi>V</mi><mrow><mi>d</mi><mi>c</mi><mo separator="true">,</mo><mi>r</mi><mi>a</mi><mi>t</mi><mi>e</mi><mi>d</mi></mrow></msub></mrow><mrow><msub><mi>V</mi><mrow><mi>d</mi><mi>c</mi><mo separator="true">,</mo><mi>a</mi><mi>c</mi><mi>t</mi><mi>u</mi><mi>a</mi><mi>l</mi></mrow></msub></mrow></mfrac></mrow><annotation encoding="application/x-tex">V_{ref,comp} = V_{ref} \\times \\frac{V_{dc,rated}}{V_{dc,actual}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.36033em;"></span><span class="strut bottom" style="height:2.332438em;vertical-align:-0.972108em;"></span><span class="base displaystyle textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.22222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.10764em;">f</span><span class="mpunct">,</span><span class="mord mathit">c</span><span class="mord mathit">o</span><span class="mord mathit">m</span><span class="mord mathit">p</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mrel">=</span><span class="mord"><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.22222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">e</span><span class="mord mathit" style="margin-right:0.10764em;">f</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mbin">×</span><span class="mord reset-textstyle displaystyle textstyle uncramped"><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span><span class="mfrac"><span class="vlist"><span style="top:0.6859999999999999em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle cramped"><span class="mord textstyle cramped"><span class="mord"><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.22222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">d</span><span class="mord mathit">c</span><span class="mpunct">,</span><span class="mord mathit">a</span><span class="mord mathit">c</span><span class="mord mathit">t</span><span class="mord mathit">u</span><span class="mord mathit">a</span><span class="mord mathit" style="margin-right:0.01968em;">l</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span style="top:-0.22999999999999998em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped frac-line"></span></span><span style="top:-0.677em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle textstyle uncramped"><span class="mord textstyle uncramped"><span class="mord"><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="vlist"><span style="top:0.15em;margin-right:0.05em;margin-left:-0.22222em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle cramped"><span class="mord scriptstyle cramped"><span class="mord mathit">d</span><span class="mord mathit">c</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.02778em;">r</span><span class="mord mathit">a</span><span class="mord mathit">t</span><span class="mord mathit">e</span><span class="mord mathit">d</span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span></span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="sizing reset-size5 size5 reset-textstyle textstyle uncramped nulldelimiter"></span></span></span></span></span></span></p><ol start="2"><li><p><strong>PFC电压环带宽优化</strong>：在保证THD的前提下尽量提高电压环带宽，减小纹波</p></li><li><p><strong>增大PFC电感</strong>：更大的电感→更小的电流纹波→更小的电容纹波电流→可以用更小的电容</p></li><li><p><strong>使用薄膜电容替代部分电解电容</strong>：薄膜电容ESR更低，高频性能更好，但容值/价格比差</p></li></ol><h3 id="_4-5-认证要求" tabindex="-1">4.5 认证要求 <a class="header-anchor" href="#_4-5-认证要求" aria-label="Permalink to &quot;4.5 认证要求&quot;">​</a></h3><h4 id="_4-5-1-iec-61000-3-2-谐波电流限制" tabindex="-1">4.5.1 IEC 61000-3-2 谐波电流限制 <a class="header-anchor" href="#_4-5-1-iec-61000-3-2-谐波电流限制" aria-label="Permalink to &quot;4.5.1 IEC 61000-3-2 谐波电流限制&quot;">​</a></h4><p>IEC 61000-3-2是家电变频必须通过的认证，规定了输入电流的各次谐波限值：</p><p><strong>Class A限值（&gt;75W的家电）：</strong></p><table tabindex="0"><thead><tr><th>谐波次数</th><th>电流限值(A)</th></tr></thead><tbody><tr><td>3</td><td>2.30</td></tr><tr><td>5</td><td>1.14</td></tr><tr><td>7</td><td>0.77</td></tr><tr><td>9</td><td>0.40</td></tr><tr><td>11</td><td>0.33</td></tr><tr><td>13</td><td>0.21</td></tr><tr><td>15~39</td><td>2.25/n</td></tr></tbody></table><p><strong>Class D限值（&lt;600W的特定设备，按mA/W计）：</strong></p><table tabindex="0"><thead><tr><th>谐波次数</th><th>限值(mA/W)</th></tr></thead><tbody><tr><td>3</td><td>3.4</td></tr><tr><td>5</td><td>1.9</td></tr><tr><td>7</td><td>1.0</td></tr><tr><td>9</td><td>0.5</td></tr><tr><td>11</td><td>0.35</td></tr><tr><td>13</td><td>0.296</td></tr></tbody></table><p><strong>通过认证的关键：</strong></p><ol><li>PFC满载PF &gt; 0.99，THD &lt; 5%</li><li>过零畸变必须控制在合理范围内</li><li>轻载（25%、50%）也需要满足要求</li><li>电网电压波动（±10%）下仍需满足</li></ol><h4 id="_4-5-2-emc认证" tabindex="-1">4.5.2 EMC认证 <a class="header-anchor" href="#_4-5-2-emc认证" aria-label="Permalink to &quot;4.5.2 EMC认证&quot;">​</a></h4><p><strong>传导EMI（EN 55032 / CISPR 32）：</strong></p><table tabindex="0"><thead><tr><th>频段</th><th>Class B (家用)</th><th>Class A (商用)</th></tr></thead><tbody><tr><td>150kHz~500kHz</td><td>56~46 dBμV</td><td>73 dBμV</td></tr><tr><td>500kHz~5MHz</td><td>46 dBμV</td><td>73 dBμV</td></tr><tr><td>5MHz~30MHz</td><td>50 dBμV</td><td>73 dBμV</td></tr></tbody></table><p><strong>辐射EMI（EN 55032）：</strong></p><table tabindex="0"><thead><tr><th>频段</th><th>Class B (10m)</th><th>Class A (10m)</th></tr></thead><tbody><tr><td>30MHz~230MHz</td><td>30 dBμV/m</td><td>40 dBμV/m</td></tr><tr><td>230MHz~1GHz</td><td>37 dBμV/m</td><td>47 dBμV/m</td></tr></tbody></table><p><strong>EMC设计要点：</strong></p><ol><li>PFC开关频率选择避开AM广播频段（535kHz~1605kHz）</li><li>EMI滤波器的共模电感需要覆盖PFC和逆变器两个频段</li><li>Y电容总容量受漏电流限制（&lt; 3.5mA for Class I设备）</li><li>PCB布局：PFC和逆变器的高频回路面积最小化</li><li>变压器/电感采用屏蔽结构，减少辐射</li></ol><h4 id="_4-5-3-安全认证" tabindex="-1">4.5.3 安全认证 <a class="header-anchor" href="#_4-5-3-安全认证" aria-label="Permalink to &quot;4.5.3 安全认证&quot;">​</a></h4><table tabindex="0"><thead><tr><th>认证</th><th>标准</th><th>关键要求</th></tr></thead><tbody><tr><td>电气安全</td><td>IEC 62368-1 / GB 4943</td><td>绝缘耐压、漏电流、接地</td></tr><tr><td>电磁兼容</td><td>IEC 61000-3-2 / GB 17625.1</td><td>谐波电流限值</td></tr><tr><td>电磁兼容</td><td>IEC 61000-3-3 / GB 17625.2</td><td>电压波动和闪烁</td></tr><tr><td>浪涌抗扰</td><td>IEC 61000-4-5</td><td>1~4kV浪涌</td></tr><tr><td>ESD抗扰</td><td>IEC 61000-4-2</td><td>接触放电±4kV, 空气放电±8kV</td></tr><tr><td>快速瞬变</td><td>IEC 61000-4-4</td><td>±1kV (信号线), ±2kV (电源线)</td></tr></tbody></table><p><strong>安全认证常见失败点：</strong></p><ol><li>Y电容漏电流超标→减小Y电容→EMI可能超标→需要优化EMI滤波器</li><li>浪涌测试损坏PFC MOSFET→增加TVS管或压敏电阻(MOV)</li><li>电压暂降时PFC失控→增加输入电压检测和软重启逻辑</li><li>ESD打火导致MCU复位→增加TVS和RC滤波</li></ol><hr><h2 id="_5-🔗-交叉视角-★★★☆☆-🔄" tabindex="-1">5. 🔗 交叉视角 ★★★☆☆ 🔄 <a class="header-anchor" href="#_5-🔗-交叉视角-★★★☆☆-🔄" aria-label="Permalink to &quot;5. 🔗 交叉视角 ★★★☆☆ 🔄&quot;">​</a></h2><h3 id="_5-1-与pmi-01的交叉" tabindex="-1">5.1 与PMI-01的交叉 <a class="header-anchor" href="#_5-1-与pmi-01的交叉" aria-label="Permalink to &quot;5.1 与PMI-01的交叉&quot;">​</a></h3><p>PMI-01讲了PFC+电机的系统架构和母线电容设计，本模块从家电成本约束角度重新审视这些设计——在家电场景下，母线电容不是&quot;够不够&quot;的问题，而是&quot;能不能再省一点&quot;的问题。</p><h3 id="_5-2-与pmi-02的交叉" tabindex="-1">5.2 与PMI-02的交叉 <a class="header-anchor" href="#_5-2-与pmi-02的交叉" aria-label="Permalink to &quot;5.2 与PMI-02的交叉&quot;">​</a></h3><p>PMI-02讲了PFC与电机控制的协同设计，本模块从家电场景出发，将协同设计原则应用到具体的单芯片方案中——ADC复用、中断优先级、制动斩波器都是PMI-02理论的工程实践。</p><h3 id="_5-3-与alg-07的交叉" tabindex="-1">5.3 与ALG-07的交叉 <a class="header-anchor" href="#_5-3-与alg-07的交叉" aria-label="Permalink to &quot;5.3 与ALG-07的交叉&quot;">​</a></h3><p>ALG-07（无传感器观测器）详细讲解了滑模观测器和高频注入的原理，本模块从家电压缩机启动角度应用了这些技术。</p><h3 id="_5-4-与alg-02的交叉" tabindex="-1">5.4 与ALG-02的交叉 <a class="header-anchor" href="#_5-4-与alg-02的交叉" aria-label="Permalink to &quot;5.4 与ALG-02的交叉&quot;">​</a></h3><p>ALG-02（电流采样时序）详细讲解了PWM同步采样的原理，本模块从单电阻采样+PFC的ADC复用角度应用了这些技术。</p><hr><h2 id="_6-🏭-工程案例-★★★☆☆-🔧" tabindex="-1">6. 🏭 工程案例 ★★★☆☆ 🔧 <a class="header-anchor" href="#_6-🏭-工程案例-★★★☆☆-🔧" aria-label="Permalink to &quot;6. 🏭 工程案例 ★★★☆☆ 🔧&quot;">​</a></h2><h3 id="案例1-1-5hp空调变频板设计" tabindex="-1">案例1：1.5HP空调变频板设计 <a class="header-anchor" href="#案例1-1-5hp空调变频板设计" aria-label="Permalink to &quot;案例1：1.5HP空调变频板设计&quot;">​</a></h3><p><strong>需求：</strong></p><ul><li>输入：220VAC/50Hz</li><li>压缩机：1.5HP BLDC（约1.1kW）</li><li>成本目标：BOM &lt; $7</li><li>认证：IEC 61000-3-2 Class A, EN 55032 Class B</li></ul><p><strong>方案选择：</strong></p><table tabindex="0"><thead><tr><th>器件</th><th>型号</th><th>成本</th></tr></thead><tbody><tr><td>MCU</td><td>GD32F303RCT6</td><td>$1.20</td></tr><tr><td>PFC MOSFET</td><td>IPA60R600P6 (600V/11A)</td><td>$0.40</td></tr><tr><td>PFC二极管</td><td>MUR860 (600V/8A)</td><td>$0.15</td></tr><tr><td>PFC电感</td><td>1mH/10A 铁硅铝</td><td>$0.50</td></tr><tr><td>逆变器IPM</td><td>STGIP10N60 (600V/10A)</td><td>$1.50</td></tr><tr><td>母线电容</td><td>450V/470μF × 1</td><td>$0.90</td></tr><tr><td>EMI滤波</td><td>共模电感+X/Y电容</td><td>$0.60</td></tr><tr><td>其他(运放/电阻/PCB)</td><td>-</td><td>$1.20</td></tr><tr><td><strong>总计</strong></td><td></td><td><strong>$6.45</strong> ✅</td></tr></tbody></table><p><strong>测试结果：</strong></p><ul><li>PF = 0.993（满载），0.985（半载）</li><li>THD = 4.8%（满载），7.2%（半载）</li><li>传导EMI：余量6dB（Class B）</li><li>压缩机启动成功率：&gt; 99%</li><li>噪声：38dB(A)@1m</li></ul><h3 id="案例2-冰箱变频板成本优化" tabindex="-1">案例2：冰箱变频板成本优化 <a class="header-anchor" href="#案例2-冰箱变频板成本优化" aria-label="Permalink to &quot;案例2：冰箱变频板成本优化&quot;">​</a></h3><p><strong>优化目标：</strong> 将BOM从$5.5降低到$4.5</p><p><strong>优化措施：</strong></p><table tabindex="0"><thead><tr><th>优化项</th><th>原方案</th><th>优化方案</th><th>节省</th></tr></thead><tbody><tr><td>MCU</td><td>STM32F103RCT6 ($1.50)</td><td>GD32E230F8 ($0.80)</td><td>$0.70</td></tr><tr><td>母线电容</td><td>450V/330μF ($0.70)</td><td>450V/220μF ($0.50)</td><td>$0.20</td></tr><tr><td>电流采样</td><td>三电阻 ($0.60)</td><td>单电阻 ($0.20)</td><td>$0.40</td></tr><tr><td>PFC电感</td><td>1.5mH ($0.60)</td><td>1.0mH ($0.45)</td><td>$0.15</td></tr><tr><td><strong>总节省</strong></td><td></td><td></td><td><strong>$1.45</strong></td></tr></tbody></table><p><strong>代价评估：</strong></p><ul><li>单电阻采样：低速性能略差，但冰箱压缩机不需要低速高精度</li><li>220μF电容：母线纹波从4.2%增加到6.3%，需要增加母线电压前馈补偿</li><li>GD32E230：Cortex-M23内核，性能比M3低，但冰箱控制算法简单够用</li></ul><p><strong>优化后BOM：$4.05 ✅</strong></p><hr><h2 id="_7-✏️-实践练习-★★☆☆☆-🎯" tabindex="-1">7. ✏️ 实践练习 ★★☆☆☆ 🎯 <a class="header-anchor" href="#_7-✏️-实践练习-★★☆☆☆-🎯" aria-label="Permalink to &quot;7. ✏️ 实践练习 ★★☆☆☆ 🎯&quot;">​</a></h2><h3 id="练习1-家电变频架构选择-★★☆☆☆" tabindex="-1">练习1：家电变频架构选择（★★☆☆☆） <a class="header-anchor" href="#练习1-家电变频架构选择-★★☆☆☆" aria-label="Permalink to &quot;练习1：家电变频架构选择（★★☆☆☆）&quot;">​</a></h3><p><strong>问题：</strong> 为以下家电产品选择变频方案，说明PFC需求、控制方式、传感器方案</p><ol><li>30W台扇（成本&lt;$2）</li><li>200W冰箱压缩机（成本&lt;$5）</li><li>1.5kW空调压缩机（成本&lt;$8）</li><li>3kW中央空调外机（成本&lt;$15）</li></ol><h3 id="练习2-adc通道分配-★★★☆☆" tabindex="-1">练习2：ADC通道分配（★★★☆☆） <a class="header-anchor" href="#练习2-adc通道分配-★★★☆☆" aria-label="Permalink to &quot;练习2：ADC通道分配（★★★☆☆）&quot;">​</a></h3><p><strong>条件：</strong> 使用GD32F303RCT6开发2kW空调变频板</p><p><strong>问题：</strong></p><ol><li>列出PFC+FOC系统所有需要ADC采样的信号</li><li>设计ADC0/ADC1/ADC2的通道分配方案</li><li>计算各ADC的采样率需求</li><li>验证ADC总占用率是否超限</li></ol><h3 id="练习3-母线电容成本优化-★★★☆☆" tabindex="-1">练习3：母线电容成本优化（★★★☆☆） <a class="header-anchor" href="#练习3-母线电容成本优化-★★★☆☆" aria-label="Permalink to &quot;练习3：母线电容成本优化（★★★☆☆）&quot;">​</a></h3><p><strong>条件：</strong> 1kW冰箱变频板，原方案使用450V/330μF电解电容</p><p><strong>问题：</strong></p><ol><li>计算原方案的母线纹波电压</li><li>如果改用220μF，纹波电压增加多少</li><li>设计母线电压前馈补偿方案</li><li>评估改用220μF后对电机转矩脉动的影响</li></ol><h3 id="练习4-emc认证问题排查-★★★★☆" tabindex="-1">练习4：EMC认证问题排查（★★★★☆） <a class="header-anchor" href="#练习4-emc认证问题排查-★★★★☆" aria-label="Permalink to &quot;练习4：EMC认证问题排查（★★★★☆）&quot;">​</a></h3><p><strong>条件：</strong> 2kW空调变频板，传导EMI在200kHz处超标8dB</p><p><strong>问题：</strong></p><ol><li>分析200kHz处超标的可能原因</li><li>提出至少3种解决方案</li><li>评估每种方案对成本的影响</li><li>选择最优方案并说明理由</li></ol><hr><blockquote><p><strong>模块关联：</strong></p><ul><li>PMI-01 PFC与电机控制系统架构（功率链路、拓扑选择）</li><li>PMI-02 PFC与电机控制协同（双环协同、制动能量管理）</li><li>PP-04 PFC功率因数校正（PFC原理、THD优化）</li><li>ALG-02 电流采样时序（ADC采样同步）</li><li>ALG-07 无传感器观测器（滑模观测器、高频注入）</li><li>HW-06 功率管理与保护（保护电路设计）</li><li>HW-07 热设计与EMC（EMI滤波器设计）</li></ul></blockquote>`,203)])])}const g=a(p,[["render",i]]);export{h as __pageData,g as default};
